const NST = {scheduled:['n',()=>L('Scheduled','مجدول'),'clock'],sent:['info',()=>L('Sent','أُرسل'),'check'],delivered:['info',()=>L('Delivered','وصل'),'check'],read:['ok',()=>L('Read','قُرئ'),'check'],failed:['bad',()=>L('Failed → in-app + SMS','فشل ← داخل التطبيق + SMS'),'alert'],skipped:['n',()=>L('Skipped (paid / promise)','تُخطّي (دُفع / وعد)'),'x']};
